export function mergePhase4Content(content) {
    content.storyline.scenes = {
        ...content.storyline.scenes,
        ...PHASE4_SCENES,
    };
    if (!content.randomEvents)
        content.randomEvents = [];
    content.randomEvents = [...content.randomEvents, ...PHASE4_EVENTS];
    return content;
}
